  ('d8069181-9886-52a4-9875-3fccf3d6e56d', 'saxony-anhalt-curriculum-repository', 'DE-ST', 'openlpm-starter-draft', 'DE-ST-LP-BIO-sjg5-6-angepasstheit-wirbeltiere', 'Sachsen-Anhalt Gymnasium Biologie Lehrplan, grades 5 to 6: Explain the adaptedness of vertebrates to their way of life and habitat', '{"id":"DE-ST-LP-BIO-sjg5-6-angepasstheit-wirbeltiere","label":"Sachsen-Anhalt Gymnasium Biologie Lehrplan, grades 5 to 6: Explain the adaptedness of vertebrates to their way of life and habitat","labelDe":"Angepasstheit der Wirbeltiere an Lebensweise und Lebensraum erläutern","sourceUrl":"https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf (23-24). Lehrplan: Fachlehrplan Gymnasium Biologie, Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022). Not reviewed by a person. The plan uses the neutral term Angepasstheit (adaptedness) and treats evolutionary descent only as one example of relatedness between two classes."},"jurisdiction":"DE-ST","issuingBody":"Ministerium für Bildung des Landes Sachsen-Anhalt (published via the Landesportal / LISA and the Bildungsserver Sachsen-Anhalt)","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"biologie","gradeFrom":5,"gradeTo":6,"topicTags":["selection_adaptation","diversity_systematics"],"lehrplanEdition":"Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022)","adoptionDate":"2022-08-01","dateGranularity":"day","statementText":"Students compare how the body structure of vertebrates suits their way of life and habitat, sort animals into vertebrate classes by typical features, and follow relatedness between two classes. Model experiments and dissection (hands-on or on screen) are required.","description":"Students compare how the body structure of vertebrates suits their way of life and habitat, sort animals into vertebrate classes by typical features, and follow relatedness between two classes. Model experiments and dissection (hands-on or on screen) are required.","verificationStatus":"primary-source-confirmed"}'),
  ('e6ed838c-a48d-5a37-859c-c41bdad8a481', 'saxony-anhalt-curriculum-repository', 'DE-ST', 'openlpm-starter-draft', 'DE-ST-LP-BIO-sjg7-8-angepasstheit-wirbellose', 'Sachsen-Anhalt Gymnasium Biologie Lehrplan, grades 7 to 8: Explain the adaptedness of invertebrates to their way of life and habitat', '{"id":"DE-ST-LP-BIO-sjg7-8-angepasstheit-wirbellose","label":"Sachsen-Anhalt Gymnasium Biologie Lehrplan, grades 7 to 8: Explain the adaptedness of invertebrates to their way of life and habitat","labelDe":"Angepasstheit von wirbellosen Tieren an Lebensweise und Lebensraum erläutern","sourceUrl":"https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf (32-33). Lehrplan: Fachlehrplan Gymnasium Biologie, Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022). Not reviewed by a person."},"jurisdiction":"DE-ST","issuingBody":"Ministerium für Bildung des Landes Sachsen-Anhalt (published via the Landesportal / LISA and the Bildungsserver Sachsen-Anhalt)","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"biologie","gradeFrom":7,"gradeTo":8,"topicTags":["selection_adaptation","diversity_systematics","ecology_populations"],"lehrplanEdition":"Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022)","adoptionDate":"2022-08-01","dateGranularity":"day","statementText":"Students explain the variety of invertebrates as a result of adaptation to way of life and habitat, assign animals to groups by their features, and link insect population growth to environmental conditions. Simple behavior experiments and an excursion are part of it.","description":"Students explain the variety of invertebrates as a result of adaptation to way of life and habitat, assign animals to groups by their features, and link insect population growth to environmental conditions. Simple behavior experiments and an excursion are part of it.","verificationStatus":"primary-source-confirmed"}'),
  ('29fbef5a-bb68-5224-b6fc-52c16d8fbcee', 'saxony-anhalt-curriculum-repository', 'DE-ST', 'openlpm-starter-draft', 'DE-ST-LP-BIO-sjg9-mensch-umwelt-reiz-verhalten', 'Sachsen-Anhalt Gymnasium Biologie Lehrplan, grade 9: Present the interactions between humans and their environment', '{"id":"DE-ST-LP-BIO-sjg9-mensch-umwelt-reiz-verhalten","label":"Sachsen-Anhalt Gymnasium Biologie Lehrplan, grade 9: Present the interactions between humans and their environment","labelDe":"Wechselwirkungen zwischen Mensch und Umwelt darstellen","sourceUrl":"https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf (38-39). Lehrplan: Fachlehrplan Gymnasium Biologie, Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022). Not reviewed by a person. Included for its behavior experiments and the competence on behavior as adapted; most of the unit deals with nervous system, senses and health."},"jurisdiction":"DE-ST","issuingBody":"Ministerium für Bildung des Landes Sachsen-Anhalt (published via the Landesportal / LISA and the Bildungsserver Sachsen-Anhalt)","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"biologie","gradeFrom":9,"gradeTo":9,"topicTags":["behavior_cognition","human_biology"],"lehrplanEdition":"Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022)","adoptionDate":"2022-08-01","dateGranularity":"day","statementText":"Students connect stimulus and response in organisms, compare nervous systems and sense organs, and run behavior experiments, including explaining behavior as adapted to circumstances. Human brain function, addiction, stress and the nerve-hormone link complete the unit.","description":"Students connect stimulus and response in organisms, compare nervous systems and sense organs, and run behavior experiments, including explaining behavior as adapted to circumstances. Human brain function, addiction, stress and the nerve-hormone link complete the unit.","verificationStatus":"primary-source-confirmed"}'),
  ('4985f7ce-c3c0-5a96-8208-3b261aa6ee37', 'saxony-anhalt-curriculum-repository', 'DE-ST', 'openlpm-starter-draft', 'DE-ST-LP-BIO-sjg9-oekosystem-wald', 'Sachsen-Anhalt Gymnasium Biologie Lehrplan, grade 9: Explain the interactions among organisms and with their environment in the forest ecosystem', '{"id":"DE-ST-LP-BIO-sjg9-oekosystem-wald","label":"Sachsen-Anhalt Gymnasium Biologie Lehrplan, grade 9: Explain the interactions among organisms and with their environment in the forest ecosystem","labelDe":"Wechselwirkungen zwischen Organismen untereinander und mit ihrer Umwelt im Ökosystem Wald erläutern","sourceUrl":"https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf (40-41). Lehrplan: Fachlehrplan Gymnasium Biologie, Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022). Not reviewed by a person."},"jurisdiction":"DE-ST","issuingBody":"Ministerium für Bildung des Landes Sachsen-Anhalt (published via the Landesportal / LISA and the Bildungsserver Sachsen-Anhalt)","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"biologie","gradeFrom":9,"gradeTo":9,"topicTags":["ecology_populations","selection_adaptation"],"lehrplanEdition":"Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022)","adoptionDate":"2022-08-01","dateGranularity":"day","statementText":"Students describe the forest ecosystem: biotic and abiotic factors, tolerance ranges, adaptation of plants to light and of animals to temperature, relationships between species, populations and food webs. They evaluate human impact, invasive species and sustainability.","description":"Students describe the forest ecosystem: biotic and abiotic factors, tolerance ranges, adaptation of plants to light and of animals to temperature, relationships between species, populations and food webs. They evaluate human impact, invasive species and sustainability.","verificationStatus":"primary-source-confirmed"}'),
  ('124ee514-b1eb-5a02-bd34-c2219666caa3', 'saxony-anhalt-curriculum-repository', 'DE-ST', 'openlpm-starter-draft', 'DE-ST-LP-BIO-sjg10-vererbung', 'Sachsen-Anhalt Gymnasium Biologie Lehrplan, grade 10: Present inheritance processes as a feature of life and apply their regularities', '{"id":"DE-ST-LP-BIO-sjg10-vererbung","label":"Sachsen-Anhalt Gymnasium Biologie Lehrplan, grade 10: Present inheritance processes as a feature of life and apply their regularities","labelDe":"Vererbungsvorgänge als Merkmal des Lebens darstellen und deren Gesetzmäßigkeiten anwenden","sourceUrl":"https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf (42-43). Lehrplan: Fachlehrplan Gymnasium Biologie, Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022). Not reviewed by a person. Schuljahrgang 10 is the Einführungsphase of the Oberstufe."},"jurisdiction":"DE-ST","issuingBody":"Ministerium für Bildung des Landes Sachsen-Anhalt (published via the Landesportal / LISA and the Bildungsserver Sachsen-Anhalt)","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"biologie","gradeFrom":10,"gradeTo":10,"topicTags":["inheritance_variation"],"lehrplanEdition":"Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022)","adoptionDate":"2022-08-01","dateGranularity":"day","statementText":"Students explain how traits are inherited and how variation arises through recombination, mutation and modification, and apply Mendel''s rules to breeding and to human traits. Selective breeding is compared with genetic engineering, and ethical questions of gene technology are discussed.","description":"Students explain how traits are inherited and how variation arises through recombination, mutation and modification, and apply Mendel''s rules to breeding and to human traits. Selective breeding is compared with genetic engineering, and ethical questions of gene technology are discussed.","verificationStatus":"primary-source-confirmed"}'),
  ('15f8a0c7-f9ce-5d58-b5c3-d352f8f571b0', 'saxony-anhalt-curriculum-repository', 'DE-ST', 'openlpm-starter-draft', 'DE-ST-LP-BIO-sjg10-evolution', 'Sachsen-Anhalt Gymnasium Biologie Lehrplan, grade 10: Interpret biological phenomena on the basis of evolution', '{"id":"DE-ST-LP-BIO-sjg10-evolution","label":"Sachsen-Anhalt Gymnasium Biologie Lehrplan, grade 10: Interpret biological phenomena on the basis of evolution","labelDe":"Biologische Phänomene auf der Grundlage der Evolution interpretieren","sourceUrl":"https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf (44-45). Lehrplan: Fachlehrplan Gymnasium Biologie, Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022). Not reviewed by a person. Schuljahrgang 10 is the Einführungsphase of the Oberstufe. A required student experiment is a model experiment on selection."},"jurisdiction":"DE-ST","issuingBody":"Ministerium für Bildung des Landes Sachsen-Anhalt (published via the Landesportal / LISA and the Bildungsserver Sachsen-Anhalt)","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"biologie","gradeFrom":10,"gradeTo":10,"topicTags":["evolution","selection_adaptation","nature_of_science"],"lehrplanEdition":"Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022)","adoptionDate":"2022-08-01","dateGranularity":"day","statementText":"Students interpret biological phenomena through evolution: variation and selection as the mechanism, evidence from fossils and homologous organs, relatedness of humans and apes, and the difference between ultimate and proximate explanations. They also weigh scientific against non-scientific views such as creationism.","description":"Students interpret biological phenomena through evolution: variation and selection as the mechanism, evidence from fossils and homologous organs, relatedness of humans and apes, and the difference between ultimate and proximate explanations. They also weigh scientific against non-scientific views such as creationism.","verificationStatus":"primary-source-confirmed"}'),
  ('027bb56f-0981-573c-af02-5035860cb8f5', 'saxony-anhalt-curriculum-repository', 'DE-ST', 'openlpm-starter-draft', 'DE-ST-LP-BIO-sjg11-12-gan-dna-zum-merkmal', 'Sachsen-Anhalt Gymnasium Biologie Lehrplan, grades 11 to 12: From DNA to trait: interpret constancy and variability of genetic information', '{"id":"DE-ST-LP-BIO-sjg11-12-gan-dna-zum-merkmal","label":"Sachsen-Anhalt Gymnasium Biologie Lehrplan, grades 11 to 12: From DNA to trait: interpret constancy and variability of genetic information","labelDe":"Von der DNA zum Merkmal – Konstanz und Variabilität der genetischen Information interpretieren","sourceUrl":"https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf (48-49). Lehrplan: Fachlehrplan Gymnasium Biologie, Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022). Not reviewed by a person. gAN is the grundlegendes Anforderungsniveau, treated here as basic level."},"jurisdiction":"DE-ST","issuingBody":"Ministerium für Bildung des Landes Sachsen-Anhalt (published via the Landesportal / LISA and the Bildungsserver Sachsen-Anhalt)","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"biologie","gradeFrom":11,"gradeTo":12,"courseLevel":"basic","topicTags":["inheritance_variation"],"lehrplanEdition":"Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022)","adoptionDate":"2022-08-01","dateGranularity":"day","statementText":"Students link DNA structure, replication and protein synthesis to traits, compare genetic and environmental variation in the light of biodiversity and evolution, and analyse inheritance with pedigrees and crosses. Gene tests, gene therapy and stem cells are discussed with ethical criteria.","description":"Students link DNA structure, replication and protein synthesis to traits, compare genetic and environmental variation in the light of biodiversity and evolution, and analyse inheritance with pedigrees and crosses. Gene tests, gene therapy and stem cells are discussed with ethical criteria.","verificationStatus":"primary-source-confirmed"}'),
  ('e3d0d5c6-bb00-53fb-bbd4-6c2d65eb799d', 'saxony-anhalt-curriculum-repository', 'DE-ST', 'openlpm-starter-draft', 'DE-ST-LP-BIO-sjg11-12-gan-umweltfaktor-oekosystem', 'Sachsen-Anhalt Gymnasium Biologie Lehrplan, grades 11 to 12: From environmental factor to ecosystem: justify variability and adaptedness of organisms', '{"id":"DE-ST-LP-BIO-sjg11-12-gan-umweltfaktor-oekosystem","label":"Sachsen-Anhalt Gymnasium Biologie Lehrplan, grades 11 to 12: From environmental factor to ecosystem: justify variability and adaptedness of organisms","labelDe":"Vom Umweltfaktor zum Ökosystem – Variabilität und Angepasstheit von Organismen begründen","sourceUrl":"https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf (50-52). Lehrplan: Fachlehrplan Gymnasium Biologie, Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022). Not reviewed by a person. Much of the unit is plant physiology; the ecology and adaptation parts are why it is recorded."},"jurisdiction":"DE-ST","issuingBody":"Ministerium für Bildung des Landes Sachsen-Anhalt (published via the Landesportal / LISA and the Bildungsserver Sachsen-Anhalt)","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"biologie","gradeFrom":11,"gradeTo":12,"courseLevel":"basic","topicTags":["ecology_populations","selection_adaptation"],"lehrplanEdition":"Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022)","adoptionDate":"2022-08-01","dateGranularity":"day","statementText":"Students explain how combined environmental factors shape where organisms occur and how adapted they are, using tolerance range, ecological niche and species relationships. Plant water balance and photosynthesis, matter cycles and the protection of biodiversity are covered as well.","description":"Students explain how combined environmental factors shape where organisms occur and how adapted they are, using tolerance range, ecological niche and species relationships. Plant water balance and photosynthesis, matter cycles and the protection of biodiversity are covered as well.","verificationStatus":"primary-source-confirmed"}'),
  ('1cf4444c-ade4-5081-b0cb-6de96bef30e9', 'saxony-anhalt-curriculum-repository', 'DE-ST', 'openlpm-starter-draft', 'DE-ST-LP-BIO-sjg11-12-gan-entstehung-biodiversitaet', 'Sachsen-Anhalt Gymnasium Biologie Lehrplan, grades 11 to 12: From the origin of life to biodiversity: explain the history and relatedness of organisms', '{"id":"DE-ST-LP-BIO-sjg11-12-gan-entstehung-biodiversitaet","label":"Sachsen-Anhalt Gymnasium Biologie Lehrplan, grades 11 to 12: From the origin of life to biodiversity: explain the history and relatedness of organisms","labelDe":"Von der Entstehung des Lebens zur Biodiversität – Geschichte und Verwandtschaft von Organismen erläutern","sourceUrl":"https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.bildung-lsa.de/files/b45de329c361a40a2f0a7211902d5815/FLP_Biologie_Gym_01082022_swd.pdf (53-54). Lehrplan: Fachlehrplan Gymnasium Biologie, Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022). Not reviewed by a person. gAN is the grundlegendes Anforderungsniveau, treated here as basic level."},"jurisdiction":"DE-ST","issuingBody":"Ministerium für Bildung des Landes Sachsen-Anhalt (published via the Landesportal / LISA and the Bildungsserver Sachsen-Anhalt)","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"biologie","gradeFrom":11,"gradeTo":12,"courseLevel":"basic","topicTags":["evolution","selection_adaptation","diversity_systematics","behavior_cognition","nature_of_science"],"lehrplanEdition":"Stand 01.08.2022 (In Kraft seit 2016, Anpassung 2022)","adoptionDate":"2022-08-01","dateGranularity":"day","statementText":"Students explain the origin and change of species with the synthetic theory of evolution: gene pool, kinds of selection, drift, speciation, phylogenetic trees, fitness and kin selection. They examine evidence and how