  ('1f95572d-ed8b-5554-98d7-54324256910a', 'thuringia-curriculum-repository', 'DE-TH', 'openlpm-starter-draft', 'DE-TH-LP-INF-mbi-10-netzwerke-internet', 'Thüringen Gymnasium Informatik Lehrplan, grade 10: Understanding and shaping networks and communication on the internet', '{"id":"DE-TH-LP-INF-mbi-10-netzwerke-internet","label":"Thüringen Gymnasium Informatik Lehrplan, grade 10: Understanding and shaping networks and communication on the internet","labelDe":"Netzwerke und Kommunikation im Internet verstehen und gestalten","sourceUrl":"https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf (31). Lehrplan: Lehrplan für das Gymnasium: Medienbildung und Informatik (Klassenstufen 5 bis 10) und Informatik (Klassenstufen 11/12), Erprobungsfassungen 2026, 2026 (Erprobungsfassung, two separate Lehrplan PDFs). Not reviewed by a person."},"jurisdiction":"DE-TH","issuingBody":"Thüringer Ministerium für Bildung, Wissenschaft und Kultur","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"informatik","unitNumber":"2.4.2","gradeFrom":10,"gradeTo":10,"topicTags":["systems_networks"],"lehrplanEdition":"2026 (Erprobungsfassung, two separate Lehrplan PDFs)","statementText":"Pupils explain how local and global networks are built and how data travels through them, including addressing and routing, the client-server model and name resolution. They model a simple network virtually and compare security measures such as firewalls.","description":"Pupils explain how local and global networks are built and how data travels through them, including addressing and routing, the client-server model and name resolution. They model a simple network virtually and compare security measures such as firewalls.","verificationStatus":"primary-source-confirmed"}'),
  ('ba268edf-a56b-5c94-b819-ed37fee2dd8a', 'thuringia-curriculum-repository', 'DE-TH', 'openlpm-starter-draft', 'DE-TH-LP-INF-mbi-10-grosse-datenmengen', 'Thüringen Gymnasium Informatik Lehrplan, grade 10: Automatically collecting and analysing large amounts of data', '{"id":"DE-TH-LP-INF-mbi-10-grosse-datenmengen","label":"Thüringen Gymnasium Informatik Lehrplan, grade 10: Automatically collecting and analysing large amounts of data","labelDe":"Große Datenmengen automatisiert erfassen und auswerten","sourceUrl":"https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.schulportal-thueringen.de/tip/resources/medien/68289?dateiname=LP_MBI_GY_Erprobung_2026-08-13.pdf (32). Lehrplan: Lehrplan für das Gymnasium: Medienbildung und Informatik (Klassenstufen 5 bis 10) und Informatik (Klassenstufen 11/12), Erprobungsfassungen 2026, 2026 (Erprobungsfassung, two separate Lehrplan PDFs). Not reviewed by a person."},"jurisdiction":"DE-TH","issuingBody":"Thüringer Ministerium für Bildung, Wissenschaft und Kultur","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"informatik","unitNumber":"2.4.3","gradeFrom":10,"gradeTo":10,"topicTags":["information_data","algorithms_programming"],"lehrplanEdition":"2026 (Erprobungsfassung, two separate Lehrplan PDFs)","statementText":"Pupils learn how large data sets are collected automatically, for example by sensors or tracking, and prepared for analysis. They write programs that store, analyse and visualise such data, and discuss how meaningful and how open to manipulation the results are.","description":"Pupils learn how large data sets are collected automatically, for example by sensors or tracking, and prepared for analysis. They write programs that store, analyse and visualise such data, and discuss how meaningful and how open to manipulation the results are.","verificationStatus":"primary-source-confirmed"}'),
  ('17e7828f-64e3-56a4-aeee-3da493a94684', 'thuringia-curriculum-repository', 'DE-TH', 'openlpm-starter-draft', 'DE-TH-LP-INF-inf-11-12-theoretische-informatik', 'Thüringen Gymnasium Informatik Lehrplan, grades 11 to 12: Learning area: theoretical computer science', '{"id":"DE-TH-LP-INF-inf-11-12-theoretische-informatik","label":"Thüringen Gymnasium Informatik Lehrplan, grades 11 to 12: Learning area: theoretical computer science","labelDe":"Lernbereich Theoretische Informatik","sourceUrl":"https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf (15-17). Lehrplan: Lehrplan für das Gymnasium: Medienbildung und Informatik (Klassenstufen 5 bis 10) und Informatik (Klassenstufen 11/12), Erprobungsfassungen 2026, 2026 (Erprobungsfassung, two separate Lehrplan PDFs). Not reviewed by a person. Content covers both course levels (gA and eA columns), so courseLevel is null. The plan states no hours."},"jurisdiction":"DE-TH","issuingBody":"Thüringer Ministerium für Bildung, Wissenschaft und Kultur","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"informatik","unitNumber":"2.1","gradeFrom":11,"gradeTo":12,"topicTags":["algorithms_programming"],"lehrplanEdition":"2026 (Erprobungsfassung, two separate Lehrplan PDFs)","statementText":"Students compare natural and formal languages, derive words with grammars, and explain finite automata and the halting problem. The advanced level adds Turing machines, computability limits, complexity classes and O notation.","description":"Students compare natural and formal languages, derive words with grammars, and explain finite automata and the halting problem. The advanced level adds Turing machines, computability limits, complexity classes and O notation.","verificationStatus":"primary-source-confirmed"}'),
  ('b421971b-05e4-5892-9add-97008eb6fe9e', 'thuringia-curriculum-repository', 'DE-TH', 'openlpm-starter-draft', 'DE-TH-LP-INF-inf-11-12-technische-informatik', 'Thüringen Gymnasium Informatik Lehrplan, grades 11 to 12: Learning area: technical computer science', '{"id":"DE-TH-LP-INF-inf-11-12-technische-informatik","label":"Thüringen Gymnasium Informatik Lehrplan, grades 11 to 12: Learning area: technical computer science","labelDe":"Lernbereich Technische Informatik","sourceUrl":"https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf (17-18). Lehrplan: Lehrplan für das Gymnasium: Medienbildung und Informatik (Klassenstufen 5 bis 10) und Informatik (Klassenstufen 11/12), Erprobungsfassungen 2026, 2026 (Erprobungsfassung, two separate Lehrplan PDFs). Not reviewed by a person. Content covers both course levels (gA and eA columns), so courseLevel is null."},"jurisdiction":"DE-TH","issuingBody":"Thüringer Ministerium für Bildung, Wissenschaft und Kultur","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"informatik","unitNumber":"2.2","gradeFrom":11,"gradeTo":12,"topicTags":["systems_networks","information_data"],"lehrplanEdition":"2026 (Erprobungsfassung, two separate Lehrplan PDFs)","statementText":"Students explain the von Neumann architecture, binary coding and binary arithmetic, and logic gates with truth tables, including flip-flops and adders. The advanced level adds fractional numbers in bit patterns, adder circuits and analog-digital converters.","description":"Students explain the von Neumann architecture, binary coding and binary arithmetic, and logic gates with truth tables, including flip-flops and adders. The advanced level adds fractional numbers in bit patterns, adder circuits and analog-digital converters.","verificationStatus":"primary-source-confirmed"}'),
  ('4125b9fe-c810-55d6-9a43-f4af6f46ad48', 'thuringia-curriculum-repository', 'DE-TH', 'openlpm-starter-draft', 'DE-TH-LP-INF-inf-11-12-praktische-informatik', 'Thüringen Gymnasium Informatik Lehrplan, grades 11 to 12: Learning area: practical computer science', '{"id":"DE-TH-LP-INF-inf-11-12-praktische-informatik","label":"Thüringen Gymnasium Informatik Lehrplan, grades 11 to 12: Learning area: practical computer science","labelDe":"Lernbereich Praktische Informatik","sourceUrl":"https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf (19-21). Lehrplan: Lehrplan für das Gymnasium: Medienbildung und Informatik (Klassenstufen 5 bis 10) und Informatik (Klassenstufen 11/12), Erprobungsfassungen 2026, 2026 (Erprobungsfassung, two separate Lehrplan PDFs). Not reviewed by a person. Content covers both course levels (gA and eA columns), so courseLevel is null."},"jurisdiction":"DE-TH","issuingBody":"Thüringer Ministerium für Bildung, Wissenschaft und Kultur","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"informatik","unitNumber":"2.3","gradeFrom":11,"gradeTo":12,"topicTags":["algorithms_programming","modelling_simulation"],"lehrplanEdition":"2026 (Erprobungsfassung, two separate Lehrplan PDFs)","statementText":"Students design, implement and compare iterative and recursive algorithms and model simple situations in an object-oriented way. They apply methods such as backtracking and divide and conquer. The advanced level adds dynamic data structures, graphs and polymorphism.","description":"Students design, implement and compare iterative and recursive algorithms and model simple situations in an object-oriented way. They apply methods such as backtracking and divide and conquer. The advanced level adds dynamic data structures, graphs and polymorphism.","verificationStatus":"primary-source-confirmed"}'),
  ('0778b9ce-5aca-57d3-99b2-0fd14876b544', 'thuringia-curriculum-repository', 'DE-TH', 'openlpm-starter-draft', 'DE-TH-LP-INF-inf-11-12-netzwerke-it-sicherheit', 'Thüringen Gymnasium Informatik Lehrplan, grades 11 to 12: Networks and IT security', '{"id":"DE-TH-LP-INF-inf-11-12-netzwerke-it-sicherheit","label":"Thüringen Gymnasium Informatik Lehrplan, grades 11 to 12: Networks and IT security","labelDe":"Netzwerke und IT-Sicherheit","sourceUrl":"https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf (22). Lehrplan: Lehrplan für das Gymnasium: Medienbildung und Informatik (Klassenstufen 5 bis 10) und Informatik (Klassenstufen 11/12), Erprobungsfassungen 2026, 2026 (Erprobungsfassung, two separate Lehrplan PDFs). Not reviewed by a person. This is one of three sections of Lernbereich Angewandte Informatik (2.4, pages 21 to 25). Content covers both course levels."},"jurisdiction":"DE-TH","issuingBody":"Thüringer Ministerium für Bildung, Wissenschaft und Kultur","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"informatik","unitNumber":"2.4.1","gradeFrom":11,"gradeTo":12,"topicTags":["systems_networks"],"lehrplanEdition":"2026 (Erprobungsfassung, two separate Lehrplan PDFs)","statementText":"Students describe how data moves through networks, including the client-server model, layers and routing, and explain compression and encryption and attacks on ciphers. They run a team project, implement a symmetric cipher and discuss data protection. The advanced level adds asymmetric encryption.","description":"Students describe how data moves through networks, including the client-server model, layers and routing, and explain compression and encryption and attacks on ciphers. They run a team project, implement a symmetric cipher and discuss data protection. The advanced level adds asymmetric encryption.","verificationStatus":"primary-source-confirmed"}'),
  ('e595ccd0-6f92-5d0a-9bcd-160ad62269f3', 'thuringia-curriculum-repository', 'DE-TH', 'openlpm-starter-draft', 'DE-TH-LP-INF-inf-11-12-wissensbasierte-systeme', 'Thüringen Gymnasium Informatik Lehrplan, grades 11 to 12: Knowledge-based systems', '{"id":"DE-TH-LP-INF-inf-11-12-wissensbasierte-systeme","label":"Thüringen Gymnasium Informatik Lehrplan, grades 11 to 12: Knowledge-based systems","labelDe":"Wissensbasierte Systeme","sourceUrl":"https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf (23-24). Lehrplan: Lehrplan für das Gymnasium: Medienbildung und Informatik (Klassenstufen 5 bis 10) und Informatik (Klassenstufen 11/12), Erprobungsfassungen 2026, 2026 (Erprobungsfassung, two separate Lehrplan PDFs). Not reviewed by a person. Only the eA column carries content in the page layout, so this section applies to the advanced level; the plan has no text for the gA column here. It is one of three sections of Lernbereich Angewandte Informatik (2.4)."},"jurisdiction":"DE-TH","issuingBody":"Thüringer Ministerium für Bildung, Wissenschaft und Kultur","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"informatik","unitNumber":"2.4.2","gradeFrom":11,"gradeTo":12,"courseLevel":"advanced","topicTags":["ai_ml","modelling_simulation"],"lehrplanEdition":"2026 (Erprobungsfassung, two separate Lehrplan PDFs)","statementText":"Students model a closed part of the world as facts and rules, implement it in a suitable system and query it. They describe a knowledge-based system as database, rules and inference engine, including depth-first search and backtracking, and judge its limits and the idea of weak AI.","description":"Students model a closed part of the world as facts and rules, implement it in a suitable system and query it. They describe a knowledge-based system as database, rules and inference engine, including depth-first search and backtracking, and judge its limits and the idea of weak AI.","verificationStatus":"primary-source-confirmed"}'),
  ('fc06c694-5718-509b-8c46-0220d534cc87', 'thuringia-curriculum-repository', 'DE-TH', 'openlpm-starter-draft', 'DE-TH-LP-INF-inf-11-12-maschinelles-lernen', 'Thüringen Gymnasium Informatik Lehrplan, grades 11 to 12: Machine learning', '{"id":"DE-TH-LP-INF-inf-11-12-maschinelles-lernen","label":"Thüringen Gymnasium Informatik Lehrplan, grades 11 to 12: Machine learning","labelDe":"Maschinelles Lernen","sourceUrl":"https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf","provenance":{"date":"2026-10-28","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read from https://www.schulportal-thueringen.de/tip/resources/medien/68487?dateiname=LP_Informatik_GY_SEK_II_Erprobung_2026-08-27.pdf (24-25). Lehrplan: Lehrplan für das Gymnasium: Medienbildung und Informatik (Klassenstufen 5 bis 10) und Informatik (Klassenstufen 11/12), Erprobungsfassungen 2026, 2026 (Erprobungsfassung, two separate Lehrplan PDFs). Not reviewed by a person. Content covers both course levels (gA and eA columns). It is one of three sections of Lernbereich Angewandte Informatik (2.4)."},"jurisdiction":"DE-TH","issuingBody":"Thüringer Ministerium für Bildung, Wissenschaft und Kultur","mandateType":"curriculum-unit","schoolType":"Gymnasium","subject":"informatik","unitNumber":"2.4.3","gradeFrom":11,"gradeTo":12,"topicTags":["ai_ml","information_data"],"lehrplanEdition":"2026 (Erprobungsfassung, two separate Lehrplan PDFs)","statementText":"Students describe basic ideas of AI such as pattern matching and machine learning, typical uses, and the role of AI in analysing big data. They use AI tools with care and discuss ethical and legal issues. The advanced level adds the main learning types, training data quality and training a model.","description":"Students describe basic ideas of AI such as pattern matching and machine learning, typical uses, and the role of AI in analysing big data. They use AI tools with care and discuss ethical and legal issues. The advanced level adds the main learning types, training data quality and training a model.","verificationStatus":"primary-source-confirmed"}')
) AS v(id, repo_slug, jurisdiction, source_repo, source_record_id, title, content)
