-- ============================================================================
-- 2. Proposed links to the units
-- ============================================================================
-- Rows are skipped when the part or the unit is missing, or when the pair is already linked in any way.

-- bio: 31 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('aac5e307-a98f-50c6-ba5d-5cc6bcd7ebdf', '492345be-09af-51af-9d54-028e0b53d5c4', 'proposed_contrasts_with', 'Sachsen grade 5 (8 hours) treats fish body form, scales and gills as adaptations to life in water. Bio-Core introduces features that help survival in a habitat in K-2, so Sachsen takes up the idea about three years later.'),
  ('aac5e307-a98f-50c6-ba5d-5cc6bcd7ebdf', 'b7286dea-b549-5e29-92b6-e61e1eeecbda', 'proposed_contrasts_with', 'Sachsen grade 5 (9 hours) relates bird body form, lungs and beak shape to flight and feeding. Bio-Core starts feature-and-habitat reasoning in K-2, so this unit places it later and with more anatomical detail.'),
  ('aac5e307-a98f-50c6-ba5d-5cc6bcd7ebdf', 'e51b0d70-238a-5da6-8d1c-390c6e3cf8a0', 'proposed_contrasts_with', 'Bayern grade 6 (26 hours) compares vertebrate classes for adaptations in movement, feeding, reproduction and senses. Bio-Core begins feature-and-habitat reasoning in K-2; here it is a full unit in lower secondary.'),
  ('ae85f5be-aead-5819-99df-8b3d431f79d1', '8794b60b-ec9b-5ab9-b810-9b5d6d0b9528', 'proposed_relates_to', 'Bayern grade 6 (8 hours) introduces a simplified model of evolution in which varied traits can bring advantages, and compares selective breeding with natural processes. This sits just above the Bio-Core 3-5 band.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', '48c88f6f-6bf7-59d6-9652-ccf632f3900d', 'proposed_relates_to', 'Bayern grade 9 (8 hours) has pupils explain how a species arose through genetic variability, natural selection and geographic isolation, and read adaptations as selective advantages. Grade 9 is one step above the 6-8 band.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'fb71e744-535a-5c0a-a924-061ae80c2c36', 'proposed_contrasts_with', 'Sachsen grade 10 (16 hours) covers the combined action of mutation, recombination, selection and isolation, with the population concept. Bio-Core builds the selection mechanism in 6-8, so Sachsen presents it about two years later.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', '15f8a0c7-f9ce-5d58-b5c3-d352f8f571b0', 'proposed_contrasts_with', 'Sachsen-Anhalt grade 10 interprets biological phenomena through variation and selection as the mechanism, with fossil and homology evidence. Bio-Core builds the four-part mechanism in 6-8, so this comes about two years later.'),
  ('b8bf5ec4-fe31-593a-8177-15b8109517b4', '1cf4444c-ade4-5081-b0cb-6de96bef30e9', 'proposed_relates_to', 'Sachsen-Anhalt grades 11 to 12 (basic) covers kinds of selection, drift, fitness and kin selection, and how knowledge about the adaptive value of behavior is produced. This matches the 9-12 step of weighing adaptive explanations.'),
  ('b8bf5ec4-fe31-593a-8177-15b8109517b4', '70d865cc-d85c-50a6-ab9a-09095817ebf3', 'proposed_relates_to', 'Sachsen grade 12 (advanced, 10 hours) uses cost-benefit analysis and fitness to explain the adaptive value of behaviour, and separates proximate from ultimate causes. It fits the 9-12 step of testing adaptive explanations.'),
  ('b8bf5ec4-fe31-593a-8177-15b8109517b4', '0ccfc0f7-f0b3-5b2d-aa64-79bc9286e907', 'proposed_relates_to', 'Bayern grade 12 (advanced, 24 hours) has pupils weigh inner and outer causes and treat one-sided biological explanations of human behaviour critically. This bears on evaluating adaptive claims in the 9-12 band.'),
  ('b8bf5ec4-fe31-593a-8177-15b8109517b4', '9fee6732-ac05-5d65-8cea-92017bd4506f', 'proposed_relates_to', 'Sachsen grade 12 (advanced, 20 hours) applies the synthetic theory with drift, chance and adaptive radiation, and assesses social Darwinism. Drift and chance as other explanations next to adaptation match the 9-12 theme.'),
  ('8a1c0b8f-8e98-526f-bd7a-8cb2795daa85', 'efddcbed-28b4-5183-a5d5-8f3a5be6c08c', 'proposed_relates_to', 'Bayern grade 9 (18 hours) covers DNA, protein synthesis, meiosis as a source of genetic variety, and genome mutations. This matches genes and mutation in the 6-8 band, with grade 9 one step above it.'),
  ('8a1c0b8f-8e98-526f-bd7a-8cb2795daa85', '2026846e-4bf2-5571-9044-b77f7c2af97c', 'proposed_contrasts_with', 'Sachsen grade 10 (25 hours) links genotype and phenotype, separates mutation from modification and applies Mendelian crosses. Bio-Core places genes, alleles and mutation in 6-8, about two years earlier.'),
  ('8a1c0b8f-8e98-526f-bd7a-8cb2795daa85', '124ee514-b1eb-5a02-bd34-c2219666caa3', 'proposed_contrasts_with', 'Sachsen-Anhalt grade 10 explains variation through recombination, mutation and modification and applies the Mendelian rules to breeding and human traits. Bio-Core covers genes, alleles and mutation in 6-8, so this comes later.'),
  ('6c0b740a-cb12-5c3d-8a32-75fc01624ddf', 'a6cb3764-7ea8-57da-b026-b795647b9e85', 'proposed_relates_to', 'Sachsen grade 12 (basic, 14 hours) uses the population-genetic species concept and the interplay of mutation, recombination, selection, isolation, migration and drift. This matches population-level genetics in the 9-12 band.'),
  ('6c0b740a-cb12-5c3d-8a32-75fc01624ddf', '1cf4444c-ade4-5081-b0cb-6de96bef30e9', 'proposed_relates_to', 'Sachsen-Anhalt grades 11 to 12 (basic) explains species change through the gene pool, kinds of selection and drift. Gene pool change over generations parallels allele frequency change in the 9-12 band.'),
  ('6c0b740a-cb12-5c3d-8a32-75fc01624ddf', '3dbc6c48-28c2-5071-bd82-157bde58b2ef', 'proposed_relates_to', 'Bayern grade 12 (basic, 18 hours) applies the synthetic theory of evolution (variation, selection, drift, isolation) to speciation and biodiversity. It covers the same forces as the 9-12 band, though the summary names no allele frequencies.'),
  ('76c205d2-33d4-5532-ba5a-cab715380b5e', '549ec3fc-b49f-5e65-b079-ae87dd7b30c5', 'proposed_contrasts_with', 'Sachsen grade 5 offers an optional unit in which pupils present on dinosaurs as extinct reptiles, using fossils. Bio-Core raises extinct organisms such as dinosaurs in K-2, so Sachsen places the topic about three years later.'),
  ('76c205d2-33d4-5532-ba5a-cab715380b5e', '53a84431-ee70-589d-8799-99b242da6c87', 'proposed_contrasts_with', 'Sachsen grade 5 (3 hours) draws vertebrate groups together by comparing breathing organs, body covering and reproduction. Bio-Core starts sorting by shared features in K-2; Sachsen adds organ comparison and prepares the idea of evolutionary development.'),
  ('a4cd9b9e-d3a1-52bd-b76f-eb6173ab7259', 'd8069181-9886-52a4-9875-3fccf3d6e56d', 'proposed_relates_to', 'Sachsen-Anhalt grades 5 to 6 has pupils sort animals into vertebrate classes by typical features and follow relatedness between two classes. This fits the 3-5 step on relatedness and common ancestry.'),
  ('a4cd9b9e-d3a1-52bd-b76f-eb6173ab7259', '549ec3fc-b49f-5e65-b079-ae87dd7b30c5', 'proposed_relates_to', 'Sachsen grade 5 optional dinosaur unit teaches extinct reptiles through fossils and basic palaeontology. Grade 5 falls in the 3-5 band, which covers extinction as the permanent loss of a species.'),
  ('ca152c60-d9a5-509f-afdb-e2e7bdf983b4', '48c88f6f-6bf7-59d6-9652-ccf632f3900d', 'proposed_relates_to', 'Bayern grade 9 (8 hours) explains how a present-day species arose through genetic variability, natural selection and geographic isolation. This matches populations diverging into new species, one grade above the 6-8 band.'),
  ('ca152c60-d9a5-509f-afdb-e2e7bdf983b4', 'fb71e744-535a-5c0a-a924-061ae80c2c36', 'proposed_relates_to', 'Sachsen grade 10 (16 hours) treats species and population concepts and the action of mutation, recombination, selection and isolation behind species diversity. Bio-Core has speciation in 6-8, so Sachsen is about two years later.'),
  ('ca152c60-d9a5-509f-afdb-e2e7bdf983b4', '5b37249a-30c2-5dd0-acf5-cc886410758d', 'proposed_contrasts_with', 'Sachsen-Anhalt grades 11 to 12 (advanced) explains species change with kinds of selection, drift and speciation. Bio-Core introduces speciation in 6-8, so this unit treats it much later, with fitness and kin selection added.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', '3dbc6c48-28c2-5071-bd82-157bde58b2ef', 'proposed_relates_to', 'Bayern grade 12 (basic, 18 hours) has pupils build phylogenetic trees and cladograms from molecular and other traits. This matches constructing a phylogeny from morphological and molecular evidence in the 9-12 band.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', 'a6cb3764-7ea8-57da-b026-b795647b9e85', 'proposed_relates_to', 'Sachsen grade 12 (basic, 14 hours) combines molecular evidence and phylogenetic trees with the species concept. It matches the evidence for common ancestry and phylogeny in the 9-12 band.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', '9fee6732-ac05-5d65-8cea-92017bd4506f', 'proposed_relates_to', 'Sachsen grade 12 (advanced, 20 hours) uses molecular evidence and phylogenetic trees and treats human evolution. It fits the 9-12 evidence theme on phylogeny, with human evolution as added content.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', '1cf4444c-ade4-5081-b0cb-6de96bef30e9', 'proposed_relates_to', 'Sachsen-Anhalt grades 11 to 12 (basic) covers phylogenetic trees, speciation and the evidence for evolution. It matches the 9-12 step on evidence and common ancestry.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', '46cd5b13-dad0-5bcf-b46a-0af023599326', 'proposed_relates_to', 'Bayern grade 10 (7 hours) places modern humans in the system of classification using anatomical and molecular features, and derives hypotheses from fossil finds. Grade 10 sits at the start of the 9-12 band.'),
  ('d8df353a-aa76-5d37-b5b4-a0cd3f1d4860', '5fb0cce1-9760-58e0-822b-2df453b233b8', 'proposed_relates_to', 'Bayern grade 12 (basic, 51 hours) covers how genetic information is stored and read, meiosis, mutations and their role in evolution, and Mendelian crosses. It spans the variation-and-inheritance theme at upper-secondary depth.'),
  ('d561e9fc-f767-5d25-94dc-6a4715f8ecd4', '46f6dd8a-a286-53d3-81e8-4cf9cafa9ca9', 'proposed_relates_to', 'Bayern grade 12 (advanced, 30 hours) covers trees and cladograms, the synthetic theory applied to speciation, coevolution and human evolution. It spans diversity of life and speciation in a single upper-secondary unit.')
) AS v(object_id, record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.id = v.record_id::uuid
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);

-- computational: 31 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('f95b2dff-2e43-597e-b8c6-a1857c0f60c7', 'd5ca2c14-ccad-5136-bd73-4954e5868155', 'proposed_contrasts_with', 'Thüringen grades 7 to 8 have pupils record everyday data in spreadsheets, choose and justify charts and discuss how data can be manipulated. Computational-Core places recording and charting data in grades 3-5, a few years earlier.'),
  ('f63a89a8-8a27-5cd6-acdf-7ed9f179442b', '846e38fe-42d8-5cc5-81b0-08c1f7180053', 'proposed_relates_to', 'Sachsen grade 7 separates information from data and covers binary coding of numbers, text and images. This matches the grades 6-8 band, where text, images and numbers are encoded in binary.'),
  ('f63a89a8-8a27-5cd6-acdf-7ed9f179442b', '89315463-ec84-546a-85b6-12981977358c', 'proposed_relates_to', 'Thüringen grades 5 to 6 teach how raster images are stored as binary data with RGB, how resolution and colour depth change storage needs, and how to convert between images and bit sequences. The grade is slightly earlier than the 6-8 band.'),
  ('f63a89a8-8a27-5cd6-acdf-7ed9f179442b', 'dd52aabd-1063-5922-9d65-aa504ea6ab88', 'proposed_contrasts_with', 'Sachsen-Anhalt grade 9 maps information onto data and works with units and number systems. Computational-Core places binary encoding of text, images and numbers in grades 6-8, so this unit comes one to three years later.'),
  ('f63a89a8-8a27-5cd6-acdf-7ed9f179442b', '6d5fec09-8aa3-596f-bf0f-e99e2f60a4d4', 'proposed_contrasts_with', 'Bayern grade 11 covers how information is coded, check sums and conversion between binary and hexadecimal. Computational-Core has pupils encode text and images in binary in grades 6-8, several years earlier.'),
  ('f63a89a8-8a27-5cd6-acdf-7ed9f179442b', 'b421971b-05e4-5892-9add-97008eb6fe9e', 'proposed_contrasts_with', 'Thüringen grades 11 to 12 explain binary coding and binary arithmetic inside technical computer science. Computational-Core treats binary encodings of data in grades 6-8, so Thüringen places the same ground much later.'),
  ('22e68923-d1f7-54a7-9cb5-6a3591c04a02', '0778b9ce-5aca-57d3-99b2-0fd14876b544', 'proposed_relates_to', 'Thüringen grades 11 to 12 explain compression and encryption within a networks unit. This fits the compression theme of the grades 9-12 band, though the summary names no link between information and bits.'),
  ('22e68923-d1f7-54a7-9cb5-6a3591c04a02', '2a41bc9f-762a-5db2-9548-69a43471bee5', 'proposed_relates_to', 'Sachsen grades 11 to 12 optional unit on mathematical methods names the limits of numerical accuracy. This matches the grades 9-12 indicator on naming a limit of a representation, such as precision, and its effect on a result.'),
  ('37a89183-dce2-506d-a724-968c6ec03d06', 'b184f374-8c48-5f65-9087-08d2e664bda1', 'proposed_relates_to', 'Sachsen grade 11 basic course covers the data life cycle, the relational model, SQL queries and visualising results, and discusses bias and reliability. These fit the strand''s path from recording data to the limits of representation.'),
  ('8c7bc083-021f-5891-b502-de2f708a1e09', 'cfba3fd7-b8ae-5a18-999f-b2eaaba35ff5', 'proposed_relates_to', 'Thüringen grades 5 to 6 use sequences and loops in a graphical programming environment, build and test programs in pairs and analyse errors. This matches the grades 3-5 band, which Thüringen reaches at its upper end.'),
  ('8c7bc083-021f-5891-b502-de2f708a1e09', 'ab4a4e7d-a541-57ff-99fe-72ea73805cf6', 'proposed_contrasts_with', 'Bayern grade 7 designs algorithms from sequences, conditional statements and loops with a programming tool. Computational-Core has pupils build programs with a sequence, a loop and a condition in grades 3-5, at least two years earlier.'),
  ('8c7bc083-021f-5891-b502-de2f708a1e09', '3837b121-7399-5bd2-a836-655903eadfc5', 'proposed_contrasts_with', 'Sachsen grade 7 describes algorithmic procedures in words and solves simple problems in a block-based environment. Computational-Core starts programs with sequences, loops and conditions in grades 3-5, so Sachsen begins later.'),
  ('8c7bc083-021f-5891-b502-de2f708a1e09', '7cfb5c53-00d2-5204-9e37-731b19b140f7', 'proposed_contrasts_with', 'Sachsen grade 8 solves tasks with sequence, branching and loops in a visual programming environment and discusses the social role of algorithms. Computational-Core covers sequence, loop and condition in grades 3-5.'),
  ('8c7bc083-021f-5891-b502-de2f708a1e09', '70442784-82c8-5215-81e9-43a3d26845bb', 'proposed_contrasts_with', 'Sachsen-Anhalt grade 9 designs and tests algorithms built from basic building blocks in a visual programming language. Computational-Core places building and testing programs from basic blocks in grades 3-5, several years earlier.'),
  ('31f4c2e2-f909-5cf1-ae61-ca82e22bda0e', '509eda69-cfdc-5680-ae9a-68b9edf67e92', 'proposed_relates_to', 'Thüringen grades 7 to 8 have pupils break problems into parts, program a microcontroller or robot, then test and debug. Decomposition and testing match the grades 6-8 band, but the summary names no written specification.'),
  ('31f4c2e2-f909-5cf1-ae61-ca82e22bda0e', '4d1795b5-2e80-5d92-b80c-f8d6ec3af5dd', 'proposed_contrasts_with', 'Sachsen grade 10 teaches modularisation with subprograms and libraries in a text-based language. Computational-Core has pupils split a problem and write a function per part in grades 6-8, up to two years earlier.'),
  ('31f4c2e2-f909-5cf1-ae61-ca82e22bda0e', 'b1570a7a-d4e9-5c93-a73c-fef268be7a5e', 'proposed_contrasts_with', 'Bayern grade 11 designs algorithms with function calls and tests programs systematically, using a list or array. Computational-Core covers functions and testing in grades 6-8, so Bayern places this about three years later.'),
  ('06ca57c6-f90e-5354-84b4-ee88dd292147', '42237913-cf37-5fba-b12d-aea7317b12de', 'proposed_relates_to', 'Sachsen advanced grades 11 to 12 judge the efficiency and complexity of algorithms with complexity classes and time cost. This matches the grades 9-12 indicator on comparing algorithms by the steps they take as input grows.'),
  ('06ca57c6-f90e-5354-84b4-ee88dd292147', '17e7828f-64e3-56a4-aeee-3da493a94684', 'proposed_relates_to', 'Thüringen grades 11 to 12 add complexity classes and O notation at the advanced level, and cover the halting problem. The efficiency comparison fits the grades 9-12 band; the summary gives no correctness argument.'),
  ('06ca57c6-f90e-5354-84b4-ee88dd292147', 'fc305800-da91-59e4-b513-051ffd269754', 'proposed_relates_to', 'Sachsen basic grades 11 to 12 cover recursion and complex problems and examine efficiency, complexity and limits of computability. The efficiency work fits the grades 9-12 band, where algorithms are compared on cost.'),
  ('06ca57c6-f90e-5354-84b4-ee88dd292147', '7aab713a-d165-52fc-a9c4-13dd0c00c06d', 'proposed_relates_to', 'Bayern advanced grade 12 compares the search effort of ordered binary trees with linked lists. This is a comparison of two structures for one task, as in the grades 9-12 indicator on comparing algorithms.'),
  ('71bc5265-fbcd-5e5a-b093-399a24bce44d', '566040eb-4212-51e2-8560-1e04029df350', 'proposed_contrasts_with', 'Sachsen grade 7 applies the input-processing-output model to daily-life systems with state diagrams and notes the limits of the model. Computational-Core models everyday systems and names what a model leaves out in grades 3-5.'),
  ('45c484c9-e753-5bb3-86af-086bc28fce31', '7216b433-ebdf-52ef-8173-35aa67d2c7be', 'proposed_contrasts_with', 'Sachsen basic grades 11 to 12 teach control and regulation, including the feedback loop, with microcontrollers and sensors. Computational-Core has pupils identify a feedback loop in a model in grades 6-8.'),
  ('45c484c9-e753-5bb3-86af-086bc28fce31', 'da92ab7f-602f-583b-a2a1-6ac418c902d7', 'proposed_relates_to', 'Sachsen advanced grades 11 to 12 optional unit simulates ecological models such as climate models, desert spread and species loss. It matches simulation of systems in the grades 6-8 band but is taught several years later.'),
  ('e6374470-9533-570e-8d98-0e5b24060f4d', 'fd4bb7f0-382d-52ba-a400-0390d3d5631a', 'proposed_relates_to', 'Bayern grade 11 explains a machine-learning method such as nearest neighbours, examines how training data affects results and implements an artificial neuron. This matches the grades 9-12 theme of machine learning from data.'),
  ('e6374470-9533-570e-8d98-0e5b24060f4d', 'bf5294cc-2ec8-5520-8c61-b5ef5699ce62', 'proposed_relates_to', 'Sachsen advanced grades 11 to 12 cover symbolic AI and machine learning, build an AI from collected data and judge explainability and bias. It handles more than one approach, as the grades 9-12 comparison does.'),
  ('e6374470-9533-570e-8d98-0e5b24060f4d', 'af489f6e-35cb-5aff-b663-a461e427dea1', 'proposed_relates_to', 'Sachsen basic grades 11 to 12 survey symbolic AI and machine learning, applying regression, decision trees, neural networks and Q-learning, and judge social effects. It fits the grades 9-12 machine-learning theme.'),
  ('e6374470-9533-570e-8d98-0e5b24060f4d', '0051f614-e6f6-5f9e-8407-9f266757a965', 'proposed_relates_to', 'Sachsen grade 9 meets supervised, unsupervised and reinforcement learning with software tools and asks how far results can be trusted given data and model. This sits at the lower edge of the grades 9-12 band.'),
  ('e6374470-9533-570e-8d98-0e5b24060f4d', 'e595ccd0-6f92-5d0a-9bcd-160ad62269f3', 'proposed_relates_to', 'Thüringen advanced grades 11 to 12 describe a knowledge-based system with depth-first search and backtracking and judge its limits and the idea of weak AI. This bears on the search and limits parts of the grades 9-12 comparison.'),
  ('e6374470-9533-570e-8d98-0e5b24060f4d', '68be01ed-eaa2-5868-9911-9b4994a05a51', 'proposed_contrasts_with', 'Thüringen grades 7 to 8 explain how generative AI models such as large language models work and where they reach limits. Computational-Core places machine learning in grades 9-12, so Thüringen starts it earlier.'),
  ('a652b045-d46e-5ad9-acfe-052eea355407', 'fc06c694-5718-509b-8c46-0220d534cc87', 'proposed_relates_to', 'Thüringen grades 11 to 12 describe machine learning and AI in analysing big data, and the advanced level covers training a model. It fits the machine-learning end of the strand, taught in grades 9-12 in Computational-Core.')
) AS v(object_id, record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.id = v.record_id::uuid
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);

-- interdisciplinary: 25 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('396e3dd9-4f22-5160-b6c7-3752caefa1b8', 'af489f6e-35cb-5aff-b663-a461e427dea1', 'proposed_relates_to', 'Sachsen grades 11 to 12, Artificial intelligence: students apply genetic algorithms and other methods. This is the algorithmic selection case that the 9-12 part sets beside biological selection, and it sits in the same grade band.'),
  ('396e3dd9-4f22-5160-b6c7-3752caefa1b8', '46f6dd8a-a286-53d3-81e8-4cf9cafa9ca9', 'proposed_relates_to', 'Bayern grade 12, Evolution: the synthetic theory of evolution is applied to speciation, and cultural and social evolution of humans is also treated. This pairs biological and cultural selection, as the 9-12 part does.'),
  ('396e3dd9-4f22-5160-b6c7-3752caefa1b8', '5b37249a-30c2-5dd0-acf5-cc886410758d', 'proposed_relates_to', 'Sachsen-Anhalt grades 11 to 12 (advanced level), origin of life to biodiversity: kinds of selection, drift and fitness, plus antibiotic resistance and cultural evolution. Both biological and cultural cases appear, in the matching band.'),
  ('6315aad7-35b7-52dc-9dd2-1b82d707a768', '8794b60b-ec9b-5ab9-b810-9b5d6d0b9528', 'proposed_relates_to', 'Bayern grade 6, Relatedness of vertebrates and evolution: a simplified model in which varied traits bring advantages, with selective breeding compared to natural processes. Grade 6 sits at the lower edge of the 6-8 band.'),
  ('6315aad7-35b7-52dc-9dd2-1b82d707a768', '15f8a0c7-f9ce-5d58-b5c3-d352f8f571b0', 'proposed_relates_to', 'Sachsen-Anhalt grade 10, Interpret biological phenomena on the basis of evolution: variation and selection as the mechanism, with a model experiment on selection. Grade 10 comes later than the 6-8 band and has no cultural case.'),
  ('6315aad7-35b7-52dc-9dd2-1b82d707a768', '620c70c3-0444-5566-ba08-2c02088147cd', 'proposed_relates_to', 'Sachsen grade 10, Evolutionary history of humans: biological and cultural evolution are considered together. This offers a cultural case beside the biological one, taught in grade 10 after the 6-8 band.'),
  ('ad0173a4-5c64-5d05-96ac-2b61810c4153', 'dcce8eb3-947b-593e-aca6-9b3665ffbb53', 'proposed_relates_to', 'Sachsen grade 7 (optional), History of computing technology: milestones from Pascal and Lovelace to Zuse and Turing. Each tool builds on earlier ones, which fits innovation spreading through a community, in the same band.'),
  ('e820dc2d-9317-57d1-8475-22a701fc486a', 'a677fff9-6447-51fa-b167-7bcca3285731', 'proposed_relates_to', 'Sachsen-Anhalt grades 11 to 12, Current developments in computing in their social context: social networks and AI are examined for effects on society. This matches the 9-12 example of an information environment.'),
  ('e820dc2d-9317-57d1-8475-22a701fc486a', 'c34e1b04-ef17-5817-b36c-1f40d72157ce', 'proposed_relates_to', 'Thüringen grades 7 to 8, social media: user-generated content and algorithmic steering are described. This is the platform example the 9-12 part uses, taught earlier than that band.'),
  ('3a112595-4435-5db0-950d-ca7c6da5160d', '053dfb6d-0bd0-5f83-92e4-683b6c0e159e', 'proposed_relates_to', 'Bayern grade 8, Behaviour: genetically based and learned: pupils judge from data whether a behaviour is mainly inherited or learned. This links behaviour to inheritance, and the grade sits inside the 6-8 band.'),
  ('3a112595-4435-5db0-950d-ca7c6da5160d', '29fbef5a-bb68-5224-b6fc-52c16d8fbcee', 'proposed_relates_to', 'Sachsen-Anhalt grade 9, interactions between humans and their environment: behavior experiments and explaining behavior as adapted to circumstances. Grade 9 is at the upper edge of the 6-8 band; most of the unit covers nerves and health.'),
  ('31b2be29-7a8c-5f98-a447-55ecf57f1ff9', '88901416-2dc4-5c7d-b1d7-9c813b294ef8', 'proposed_relates_to', 'Sachsen grade 5, Mammals in their habitats: pupils observe communication, cooperation, rank order and territory in wild and domestic mammals. This supports comparing behavior across species, in the 3-5 band.'),
  ('31b2be29-7a8c-5f98-a447-55ecf57f1ff9', 'e51b0d70-238a-5da6-8d1c-390c6e3cf8a0', 'proposed_relates_to', 'Bayern grade 6, Biodiversity in vertebrates: signals within a species and parental investment are compared across vertebrate classes. Grade 6 is just above the 3-5 band, which compares behavior across species.'),
  ('5d938d91-e81b-516c-ba58-a234b6d5559f', '081db851-540a-5cc0-9947-255b8adfa962', 'proposed_relates_to', 'Thüringen grade 9, Opinion formation in digital media worlds: filter bubbles created by personalisation and the influence of large platforms. This fits the 9-12 case of a recommendation algorithm; grade 9 is at the band''s lower edge.'),
  ('5d938d91-e81b-516c-ba58-a234b6d5559f', '68be01ed-eaa2-5868-9911-9b4994a05a51', 'proposed_relates_to', 'Thüringen grades 7 to 8, Searching and evaluating information II: how algorithms filter and personalise results, and where generative AI reaches limits. It relates to designed systems with emergent effects, taught before the 9-12 band.'),
  ('5d938d91-e81b-516c-ba58-a234b6d5559f', '0ccfc0f7-f0b3-5b2d-aa64-79bc9286e907', 'proposed_relates_to', 'Bayern grade 12, Behavioural ecology (advanced): communication and primate social behaviour including humans, weighing inner and outer causes. It supports comparing agency across organisms, in the 9-12 band.'),
  ('a64224d1-ac36-5b1c-b475-3c5af3aa4656', '8794b60b-ec9b-5ab9-b810-9b5d6d0b9528', 'proposed_relates_to', 'Bayern grade 6, Relatedness of vertebrates and evolution: selective breeding by humans is compared with natural processes. This is the breeder example used in the 3-5 part, taught at the top edge of that band.'),
  ('a64224d1-ac36-5b1c-b475-3c5af3aa4656', '19efbc4a-203e-5423-938a-9ec4fa436b12', 'proposed_relates_to', 'Bayern grade 5, Gaining knowledge, communicating, evaluating: pupils learn the steps of a scientific investigation and see that scientific knowledge changes over time. This relates to testing ideas, in the 3-5 band.'),
  ('a64224d1-ac36-5b1c-b475-3c5af3aa4656', '081bc218-8565-5d8e-9de4-56ae8526902a', 'proposed_relates_to', 'Bayern grade 6, Gaining knowledge, communicating, evaluating: variables, control experiments and error sources. This relates to testing a guess, in the grade 6 position between the 3-5 and 6-8 bands.'),
  ('d2dc3119-7af8-55d8-8bfe-b63a4ec56acb', '51342b1f-b6e1-5480-8b1f-53570d71dba4', 'proposed_relates_to', 'Bayern grade 8, Gaining knowledge, communicating, evaluating: pupils plan investigations, interpret data with error sources and discuss how knowledge grows and what models can show. Same grade band as the 6-8 part.'),
  ('d2dc3119-7af8-55d8-8bfe-b63a4ec56acb', 'be92fd0d-224d-5d9c-a61e-da2f03bdef66', 'proposed_relates_to', 'Bayern grade 9, Gaining knowledge, communicating, evaluating: hypothesis-driven investigations, judging data validity and developing alternative models, with evolution research as an example. Grade 9 is at the band''s upper edge.'),
  ('ba60a3be-0135-5b53-b88f-a7aecfe0ed96', 'fb71e744-535a-5c0a-a924-061ae80c2c36', 'proposed_relates_to', 'Sachsen grade 10, Origin of species diversity: pupils meet historical ideas of evolution from Linnaeus, Lamarck and Darwin. This gives the history of evolutionary thought that the 9-12 part examines, one year before the band.'),
  ('ba60a3be-0135-5b53-b88f-a7aecfe0ed96', '1a0d1f58-32a5-5833-a5a6-c200107a3619', 'proposed_relates_to', 'Bayern grades 12 to 13, competence frame for the Qualifikationsphase: forming hypotheses and reflecting on falsifiability and the provisional status of scientific knowledge. Same grade band as the 9-12 part.'),
  ('ba60a3be-0135-5b53-b88f-a7aecfe0ed96', '2e027ccf-7c84-5452-bdb0-436a88df0d81', 'proposed_relates_to', 'Bayern grade 10, Gaining knowledge, communicating, evaluating: limits, provisional status and subjectivity of scientific knowledge, and revising alternative models. Grade 10 is one year before the 9-12 band.'),
  ('ba60a3be-0135-5b53-b88f-a7aecfe0ed96', '1cf4444c-ade4-5081-b0cb-6de96bef30e9', 'proposed_relates_to', 'Sachsen-Anhalt grades 11 to 12, origin of life to biodiversity: students examine evidence and how knowledge about the adaptive value of behavior is produced. This relates to how evolutionary ideas are tested, in the 9-12 band.')
) AS v(object_id, record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.id = v.record_id::uuid
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);
